/**
 * Generate the published package's README from the repository one.
 *
 * npm resolves README relative to the *package* directory, not the repo root —
 * the same rule that applies to LICENSE. With the only README at the root,
 * 0.3.0 shipped with no documentation at all and its npm page was blank.
 *
 * Generated rather than maintained by hand, and regenerated by `prepublishOnly`,
 * so the two cannot drift. Two things have to change on the way across:
 *
 *   · Image paths. npm renders README without any repo context, so
 *     `docs/hero.png` resolves to nothing. They become absolute raw URLs.
 *   · Audience. Everything below the design-notes divider is the engineering
 *     record — worth keeping in the repo, noise on a package page.
 */

import { readFileSync, writeFileSync } from 'node:fs'
import { dirname, resolve } from 'node:path'
import { fileURLToPath } from 'node:url'

const root = resolve(dirname(fileURLToPath(import.meta.url)), '..')
const RAW = 'https://raw.githubusercontent.com/SatyadipPaul/isoform/main'
const REPO = 'https://github.com/SatyadipPaul/isoform'

const src = readFileSync(resolve(root, 'README.md'), 'utf8')

/* Consumer-facing half only. */
const cut = src.indexOf('# Design notes')
let out = cut === -1 ? src : src.slice(0, cut)

/* Relative links have no meaning on npm. Images must be absolute; the LICENSE
   link should point at the repo rather than 404 inside a tarball. */
out = out.replace(/!\[([^\]]*)\]\((docs\/[^)]+)\)/g, `![$1](${RAW}/$2)`)
out = out.replace(/\[LICENSE\]\(LICENSE\)/g, `[LICENSE](${REPO}/blob/main/LICENSE)`)

/* The build-and-test instructions are for people with the repo checked out. */
const dev = out.indexOf('## Developing this repo')
if (dev !== -1) {
  out = `${out.slice(0, dev)}## Contributing

Source, design notes and the full engineering record: [${REPO}](${REPO}).
`
}

out = `${out.trimEnd()}\n`
writeFileSync(resolve(root, 'packages/isoform/README.md'), out)

const lines = out.split('\n').length
console.log(`packages/isoform/README.md written (${lines} lines)`)
